// SourceValue says where releases come from and what they are called.
//
// It is the whole of what the source implementation hard-coded. Every field is a
// property of one product's distribution, not of the update mechanism, so
// keeping them as constants is what made that implementation un-reusable.
//
// StableRepo and DevRepo can differ, and the reason is worth stating: a project
// whose source repository goes private still has to serve already-installed
// binaries their update path, which means a public mirror for stable releases
// while candidates stay in the source repository behind credentials the public
// binary does not carry. When DevRepo is empty, StableRepo serves both.
type SourceValue struct {
	// Owner is the release host account, e.g. "kodflow".
	Owner string
	// StableRepo is the repository serving stable releases.
	StableRepo string
	// DevRepo is the repository serving release candidates. Empty means
	// candidates come from StableRepo too.
	DevRepo string
	// Product is the binary's name. It is both the archive-asset stem
	// ("<product>_<goos>_<goarch>.tar.gz") and, uppercased, the environment
	// variable prefix for the two opt-ins.
	Product string
}

// Service replaces the running binary with a newer signed release of the
// product its SourceValue names.
// It manages version checking via GitHub API and binary replacement.
// goos/goarch are captured at construction time so the per-platform asset
// resolution (`getBinaryName`, `getArchiveSuffix`, `innerBinaryName`) is
// stable per-instance — tests can construct a literal with explicit values
// instead of mutating package-level `runtimeGOOS`/`runtimeGOARCH` (which
// would race under t.Parallel).
type Service struct {
	version string
	goos    string
	goarch  string
	client  Getter
	fs      FileSystem
	copier  Copier
	// elevate replaces execPath with tmpPath when the plain rename in
	// finalizeReplacement fails with a permission error — the same
	// non-interactive sudo escalation the devcontainer installer scripts
	// use for a root-owned install directory. Swappable so tests can
	// exercise both outcomes without shelling out to a real sudo.
	//
	// The default is guardedSudoMove, NOT sudoMove: escalation requires an
	// explicit opt-in (see elevation.go).
	elevate func(tmpPath, execPath string) error
	// src says which project's releases this binary updates itself from. It
	// carries what the source implementation kept as package constants, which
	// is precisely what made that implementation serve exactly one product.
	src SourceValue
	// vendorKey is the ed25519 public half every release must be signed
	// with, set via WithVendorKey. Empty by default, and an empty key
	// refuses every install rather than skipping verification — see
	// signature.go for why that direction is the only safe one.
	vendorKey ed25519.PublicKey
	// vendorKeys are the keys a release may be signed with, in order, the
	// first of them vendorKey (keys.go, ADR 0150); domain is the signature
	// domain; clock is what the signed expiry is read against — pkg/v1/clock's
	// system clock when nil, a manual one in a suite (ADR 0158 §2).
	vendorKeys []ed25519.PublicKey
	domain     string
	clock      clock.Clock
	// probe is what a replacement must answer before it stands (probe.go).
	probe probeSpec
	// automatic is WithAutomaticConsent's (consent_product.go).
	automatic bool
}

// WithVendorKey pins the ed25519 public half every release must be signed
// with, and returns the Service so construction reads as one expression —
// the same chaining shape license.NewService(...).WithVersion(...) uses.
//
// A Service built WITHOUT this call authenticates nothing and therefore
// installs nothing: verifyArchive refuses with coreupd.NoVendorKey before a single
// byte is fetched. That default is deliberate. The alternative — treat an
// absent key as "verification not required" — would mean any construction
// site that forgot the call silently reverted to the unauthenticated
// behaviour this file exists to end, and nothing would ever fail to point it
// out.
func (s *Service) WithVendorKey(key []byte) *Service {
	return s.withVendorKey(key)
}
